package io.github.miklires.mauction;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class AuctionRepositoryTest{AuctionRepository repo;@BeforeEach void open(){repo=new AuctionRepository("jdbc:h2:mem:"+UUID.randomUUID()+";DB_CLOSE_DELAY=-1");repo.initialize().join();}@AfterEach void close(){repo.close();}@Test void onlyOneBuyerCanReserve(){UUID seller=UUID.randomUUID();Listing listing=repo.create(seller,"Seller",new byte[]{1,2},10,Instant.now().plusSeconds(60)).join();assertEquals(PurchaseResult.Status.RESERVED,repo.reserve(listing.id(),UUID.randomUUID(),"A").join().status());assertEquals(PurchaseResult.Status.NOT_ACTIVE,repo.reserve(listing.id(),UUID.randomUUID(),"B").join().status());}@Test void ownerCannotBuyOwnListing(){UUID seller=UUID.randomUUID();Listing listing=repo.create(seller,"Seller",new byte[]{1},10,Instant.now().plusSeconds(60)).join();assertEquals(PurchaseResult.Status.OWN_LISTING,repo.reserve(listing.id(),seller,"Seller").join().status());}}
